#!/usr/bin/env python3
from pathlib import Path
import shutil, sys
if len(sys.argv)!=3: raise SystemExit('usage: transform base candidate')
base=Path(sys.argv[1]); root=Path(sys.argv[2])
if root.exists(): shutil.rmtree(root)
shutil.copytree(base, root)

vgn=root/'app/src/main/java/com/hinnka/mycamera/processor/GlesIris26529SpatialRgbChromaPostprocessor.kt'
s=vgn.read_text()
old='''            float microChromaWeight = 0.0;\n            float microNearWeight = 0.0;\n            float microMomentXX = 0.0;\n            float microMomentYY = 0.0;\n            float microMomentXY = 0.0;'''
new='''            float microChromaWeight = 0.0;\n            float microNearWeight = 0.0;\n            float microMomentXX = 0.0;\n            float microMomentYY = 0.0;\n            float microMomentXY = 0.0;\n            /* IRIS_26580_MICRO_OBJECT_AREA_VS_RIBBON\n             * Track independent near-field horizontal/vertical occupancy. A genuine tiny printed\n             * object may change hue inside only a few pixels, but it still occupies area in both\n             * image axes. A one-pixel CFA/text fringe remains line-like even when it is diagonal.\n             */\n            float microNearLeft = 0.0;\n            float microNearRight = 0.0;\n            float microNearUp = 0.0;\n            float microNearDown = 0.0;'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
old='''                        microChromaWeight += w;\n                        if (abs(xx) <= 1 && abs(yy) <= 1) microNearWeight += w;\n                        microMomentXX += w * float(xx * xx);'''
new='''                        microChromaWeight += w;\n                        if (abs(xx) <= 1 && abs(yy) <= 1) {\n                            microNearWeight += w;\n                            if (xx < 0) microNearLeft = max(microNearLeft, w);\n                            if (xx > 0) microNearRight = max(microNearRight, w);\n                            if (yy < 0) microNearUp = max(microNearUp, w);\n                            if (yy > 0) microNearDown = max(microNearDown, w);\n                        }\n                        microMomentXX += w * float(xx * xx);'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
old='''            float microAreaEvidence = smoothstep(2.15, 4.25, microChromaWeight) *\n                smoothstep(2.20, 4.60, microNearWeight) *\n                smoothstep(0.16, 0.46, microMinorMoment) * centerChromaPresent;\n            /* Strong Bayer-phase evidence can nearly extinguish this new veto because repeated\n             * near-opposite/far-matching phase structure is the strongest false-color proof. Real\n             * micro-objects still win through occupancy when that phase proof is not overwhelming. */\n            float microObjectProtection = microAreaEvidence * (1.0 - 0.95 * phaseLikeEvidence);'''
new='''            float microAreaEvidence = smoothstep(1.35, 3.25, microChromaWeight) *\n                smoothstep(1.15, 2.75, microNearWeight) *\n                smoothstep(0.10, 0.32, microMinorMoment) * centerChromaPresent;\n            float microHorizontalPresence = max(microNearLeft, microNearRight);\n            float microVerticalPresence = max(microNearUp, microNearDown);\n            float microTwoAxisEvidence = smoothstep(0.18, 0.60, microHorizontalPresence) *\n                smoothstep(0.18, 0.60, microVerticalPresence);\n            float microCompactAreaEvidence = microAreaEvidence * microTwoAxisEvidence;\n            /* IRIS_26580_FAIL_CLOSED_MULTICOLOR_OBJECT_VETO\n             * Compact 2-D chroma wins over weak/moderate phase resemblance, which is common inside\n             * tiny multicolor prints. Only an overwhelming repeated near-opposite/far-matching phase\n             * signature can extinguish this veto; that preserves the proven 26578 neutral CFA-fringe\n             * regression. Uncertain cases remain biased toward keeping scene color. */\n            float phaseOverride = smoothstep(0.78, 0.96, phaseLikeEvidence);\n            float microObjectProtection = max(\n                microAreaEvidence * (1.0 - 0.98 * phaseOverride),\n                microCompactAreaEvidence * (1.0 - phaseOverride));'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
vgn.write_text(s)

sabre=root/'app/src/main/java/com/hinnka/mycamera/processor/GlesMgcRawSabreShaders.kt'
s=sabre.read_text()
old='''            float sampleY[4];\n            float maxYDelta = 0.0;\n            float maxChromaMagnitude = 0.0;\n            for (int i = 0; i < 4; ++i) {\n                sampleY[i] = irisLuma(samples[i]);\n                maxChromaMagnitude = max(maxChromaMagnitude,\n                    length(samples[i] - vec3(sampleY[i])));\n            }'''
new='''            float sampleY[4];\n            vec3 sampleChroma[4];\n            float sampleChromaMagnitude[4];\n            float maxYDelta = 0.0;\n            float maxChromaMagnitude = 0.0;\n            for (int i = 0; i < 4; ++i) {\n                sampleY[i] = irisLuma(samples[i]);\n                sampleChroma[i] = samples[i] - vec3(sampleY[i]);\n                sampleChromaMagnitude[i] = length(sampleChroma[i]);\n                maxChromaMagnitude = max(maxChromaMagnitude, sampleChromaMagnitude[i]);\n            }'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
old='''            float bilinearY = max(irisLuma(bilinearGuide), 0.0);\n            float selectorY = mix(sampleY[nearestIndex], directY, 0.40 * confidence);\n            vec3 topologyChroma = vec3(0.0);\n            float weight = 0.0;\n            for (int i = 0; i < 4; ++i) {\n                float relativeY = abs(sampleY[i] - selectorY) /\n                    max(max(abs(sampleY[i]), abs(selectorY)), 0.035);\n                float sameMaterial = 1.0 / (1.0 + 18.0 * relativeY * relativeY);\n                float w = spatial[i] * max(sameMaterial, 0.015);\n                topologyChroma += (samples[i] - vec3(sampleY[i])) * w;\n                weight += w;\n            }\n            topologyChroma /= max(weight, 1.0e-6);\n            float topologyMagnitude = length(topologyChroma);\n            if (topologyMagnitude > maxChromaMagnitude && topologyMagnitude > 1.0e-7)\n                topologyChroma *= maxChromaMagnitude / topologyMagnitude;\n            vec3 bilinearChroma = bilinearGuide - vec3(bilinearY);\n            float edgeGate = irisSmooth01((maxYDelta - 0.025) / 0.130);\n            vec3 selectedChroma = mix(bilinearChroma, topologyChroma, edgeGate);'''
new='''            float bilinearY = max(irisLuma(bilinearGuide), 0.0);\n            /* IRIS_26580_TRUE2X_SAME_MATERIAL_CHROMA_OWNERSHIP\n             * Direct-CFA remains luma-only. Its temporally proven 2x luma is used only to choose\n             * which native VGN material side owns this output pixel. Cross-edge samples receive no\n             * meaningful floor weight, preventing a colored native edge pixel from painting the\n             * neighboring neutral glyph/background side. */\n            float selectorY = mix(sampleY[nearestIndex], directY, 0.60 * confidence);\n            vec3 topologyChroma = vec3(0.0);\n            float weight = 0.0;\n            float crossSideSpatial = 0.0;\n            float localChromaOccupancy = 0.0;\n            float neutralVotes = 0.0;\n            int anchorIndex = nearestIndex;\n            float anchorScore = -1.0;\n            for (int i = 0; i < 4; ++i) {\n                float relativeY = abs(sampleY[i] - selectorY) /\n                    max(max(abs(sampleY[i]), abs(selectorY)), 0.035);\n                float sameMaterial = 1.0 - irisSmooth01((relativeY - 0.08) / 0.32);\n                float materialWeight = sameMaterial * sameMaterial;\n                float w = spatial[i] * (0.002 + 0.998 * materialWeight);\n                topologyChroma += sampleChroma[i] * w;\n                weight += w;\n                crossSideSpatial += spatial[i] * (1.0 - sameMaterial);\n                localChromaOccupancy += spatial[i] *\n                    irisSmooth01((sampleChromaMagnitude[i] - 0.020) / 0.055);\n                neutralVotes += 1.0 - irisSmooth01((sampleChromaMagnitude[i] - 0.010) / 0.050);\n                float score = spatial[i] * (0.15 + 0.85 * sameMaterial);\n                if (score > anchorScore) { anchorScore = score; anchorIndex = i; }\n            }\n            topologyChroma /= max(weight, 1.0e-6);\n            float topologyMagnitude = length(topologyChroma);\n            if (topologyMagnitude > maxChromaMagnitude && topologyMagnitude > 1.0e-7)\n                topologyChroma *= maxChromaMagnitude / topologyMagnitude;\n            vec3 bilinearChroma = bilinearGuide - vec3(bilinearY);\n            float edgeGate = irisSmooth01((maxYDelta - 0.018) / 0.095);\n            float crossEdgeEvidence = irisSmooth01((crossSideSpatial - 0.06) / 0.30);\n            float topologyGate = edgeGate * mix(0.70, 1.0, crossEdgeEvidence);\n            vec3 selectedChroma = mix(bilinearChroma, topologyChroma, topologyGate);\n\n            /* IRIS_26580_NEUTRAL_GLYPH_OUTSIDE_EDGE_EXCLUSION\n             * Do not identify text semantically. When at least three of the four native guide\n             * samples are neutral and the high-resolution luma-selected owner is also neutral, any\n             * chroma arriving mainly from the opposite material side is unsupported. Pull only\n             * toward that already-existing neutral owner chroma. A nearby tiny colored print is\n             * protected whenever its spatially owned chroma occupancy is strong. */\n            vec3 anchorChroma = sampleChroma[anchorIndex];\n            float anchorNeutral = 1.0 -\n                irisSmooth01((sampleChromaMagnitude[anchorIndex] - 0.012) / 0.050);\n            float neutralNeighborhood = irisSmooth01((neutralVotes - 2.55) / 0.90);\n            float localColorProtection = irisSmooth01((localChromaOccupancy - 0.20) / 0.40);\n            float neutralSideOwnership = edgeGate * crossEdgeEvidence * anchorNeutral *\n                neutralNeighborhood * (1.0 - localColorProtection);\n            selectedChroma = mix(selectedChroma, anchorChroma, 0.92 * neutralSideOwnership);'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new)
sabre.write_text(s)

vp=root/'app/version.properties'
v=vp.read_text()
assert v.count('VERSION_NAME=0.9726579')==1
assert v.count('VERSION_BUILD=26579')==1
v=v.replace('VERSION_NAME=0.9726579','VERSION_NAME=0.9726580').replace('VERSION_BUILD=26579','VERSION_BUILD=26580')
vp.write_text(v)
print('PASS transformed 26579 -> 26580 refinement candidate')
